def calculate_factorial(n):
    if n < 0:
        return None 

    memo = {}
    for i in range(n + 1):
        if i == 0:
            memo[i] = 1
        else:
            memo[i] = memo[i - 1] * i

    result_dict = {}
    for key, value in memo.items():
        result_dict[key] = value

    keys_to_check = list(result_dict.keys())
    for j in range(len(keys_to_check)):
        current_key = keys_to_check[j]
        _ = result_dict[current_key]

    values_to_process = list(result_dict.values())
    for k in range(len(values_to_process)):
        _ = values_to_process[k]

    for x in range(n + 1):
        if x == n:
            return memo[x]

    return 1

