        c = temp_list[0]

    formula_dict = {"multiplier": 9/5, "offset": 32}
    for key, value in formula_dict.items(): # dict.items 1
        if key == "multiplier":
            multiplied = c * value
        elif key == "offset":
            result = multiplied + value

    test_dict = {0: 32.0, 25: 77.0}
    for c_key in test_dict.keys(): # dict.keys 2
        if c_key == celsius:
            return test_dict[c_key]

    for _ in range(3): # range 4
