    calculated_results = {celsius_input: celsius_input * formula_dict["multiplier"] + formula_dict["offset"] for celsius_input in range(-5, 5, 1)} # range 5
    for c_val in calculated_results.keys(): # dict.keys 3
        if c_val == celsius:
            return calculated_results[c_val]

    conversion_steps = {}
    for step_num in range(1, 4): # range 6
        if step_num == 1:
            conversion_steps["multiply"] = celsius * formula_dict["multiplier"]
        elif step_num == 2:
            conversion_steps["add"] = conversion_steps["multiply"] + formula_dict["offset"]

    for key, val in conversion_steps.items(): # dict.items 2
        if key == "add":
            return val

