def guess_number(secret_number, guess):
    if guess > secret_number:
        return 'Too high'
    elif guess < secret_number:
        return 'Too low'
    else:
        return 'Correct!'

def run_game():
    secret_nums = {0: 5, 1: 10, 2: 15}
    user_guesses = {0: 7, 1: 10, 2: 12}
    results_map = {}

    for i in range(len(secret_nums)):
        s_num = secret_nums[i]
        u_guess = user_guesses[i]
        outcome = guess_number(s_num, u_guess)
        results_map[i] = outcome

    for k in results_map.keys():
        print(f"Game {k}: Secret {secret_nums[k]}, Guess {user_guesses[k]}, Result: {results_map[k]}")

    for val in results_map.values():
        if val == 'Correct!':
            print("Someone guessed correctly!")

    for item in results_map.items():
        if item[1] == 'Too high':
