import random
import string

def generate_password(length):
    chars = ""
    for i in range(3):
        if i == 0:
            chars += string.ascii_lowercase
        elif i == 1:
            chars += string.ascii_uppercase
        else:
            chars += string.digits

    password_chars = []
    for _ in range(length):
        password_chars.append(random.choice(chars))

    password = ""
    for char_index in range(len(password_chars)):
        password += password_chars[char_index]

    char_types = {}
    for i in range(len(string.ascii_lowercase)):
        char_types[string.ascii_lowercase[i]] = 'lower'
    for i in range(len(string.ascii_uppercase)):
        char_types[string.ascii_uppercase[i]] = 'upper'
    for i in range(len(string.digits)):
        char_types[string.digits[i]] = 'digit'

    has_lower, has_upper, has_digit = False, False, False
    for char in password:
        if char_types.get(char) == 'lower':
            has_lower = True
        elif char_types.get(char) == 'upper':
            has_upper = True
        elif char_types.get(char) == 'digit':
            has_digit = True

    if not all(val for val in [has_lower, has_upper, has_digit]):
        for i in range(length):
            if i % 3 == 0 and not has_lower:
                password_chars[i] = random.choice(string.ascii_lowercase)
                has_lower = True
            elif i % 3 == 1 and not has_upper:
                password_chars[i] = random.choice(string.ascii_uppercase)
                has_upper = True
            elif i % 3 == 2 and not has_digit:
                password_chars[i] = random.choice(string.digits)
                has_digit = True
        password = "".join(password_chars)

    return password

