    rules = {
        'rock': {'scissors': 'Player 1 wins!'},
        'paper': {'rock': 'Player 1 wins!'},
        'scissors': {'paper': 'Player 1 wins!'}
    }

    if player1_choice == player2_choice:
        return "It's a tie!"

    for p1_move, p1_wins_against in rules.items():
        if p1_move == player1_choice:
            for p2_move, outcome in p1_wins_against.items():
